import re
from time import sleep
from taf.ul.bts_components import Smod

from taf.rfrl.procedures.resources.python.connections import get_ssh_connection_credentials
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_step
from taf.rfrl.procedures.resources.python.gnss.exceptions import (
    GnssSwUpdateError,
    GnssInfoError,
)


class Gnss:
    """
    Supports GNSS operations.
    """

    def __init__(self):
        self.smod = Smod()
        self.device_info = None
        self.proto_info = None
        self.device_cmd = '/opt/hwmt/python/sendommessage.sh -s 0x04cb -d HWAGNSS-1/DEVICE-1'
        self.proto_cmd = '/opt/hwmt/python/sendommessage.sh -s 0x04cb -d HWAGNSS-1 --proto GNSS/hwagnss'

    @log_input_and_output
    def update_gnss_software(self, bts_type='GNB'):
        """
        Updates GNSS software if GNSS SW version in BTS packages is different than actual GNSS SW version.
        Waits 20 minutes for GNSS SW update to finish.

        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        :raises GnssSwUpdateError: if GNSS software update not successful within 20 minutes
        """
        if self._is_current_gnss_sw_version_identical_to_bts_package(bts_type=bts_type):
            return

        self._enable_gnss_device(bts_type=bts_type)
        path_to_gnss_sw = self._get_smod_path_to_gnss_sw(bts_type=bts_type)

        log_step(f'GNSS SW update for {bts_type} is ongoing...')

        self._execute_on_smod(command=f'{self.device_cmd}/MANAGEMENT-1 --proto GNSS/management -t execute '
                                      f'--action upgradeSw --args pathToFile={path_to_gnss_sw}', bts_type=bts_type)
        self._wait_for_sw_upgrade_status_finished(bts_type=bts_type)

    @log_input_and_output
    def is_gnss_in_configuration(self, bts_type='GNB'):
        """
        Checks if GNSS is in configuration.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        :return: True if GNSS is in configuration, False otherwise
        :rtype: bool
        """
        hw_type = self._get_gnss_parameter_value('hwType', expect_missing=True, bts_type=bts_type)
        return False if hw_type == '' else True

    @log_input_and_output
    def _get_gnss_parameter_value(self, parameter, expect_missing=False, bts_type='GNB'):
        """
        Gets GNSS parameter value from SMOD.
        :param parameter: GNSS parameter to get, e.g. 'hwType', 'hwVersion', 'swVersionMajor', 'swVersionMinor'
        :type parameter: str
        :param expect_missing: if True, returns '' if parameter is not found in GNSS device info; default value: False
        :type expect_missing: bool
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        :return: GNSS parameter value
        :rtype: str
        :raises GnssInfoError: if GNSS parameter should exist and cannot be found in GNSS device info
        """
        if self.device_info is None:
            self._get_device_info(bts_type=bts_type)

        if expect_missing:
            if parameter.lower() not in self.device_info.lower():
                return ''

        try:
            return re.search(f'{parameter}: (.*)', self.device_info, re.IGNORECASE).group(1).strip('"\n\r')
        except AttributeError:
            raise GnssInfoError(
                f'Cannot get GNSS {parameter} from SMOD.\n'
                f'Please check if GNSS is in configuration or if required parameter exists in info.\n'
                f'GNSS device info: {self.device_info}')

    @log_input_and_output
    def _get_gnss_proto_parameter_value(self, parameter, bts_type='GNB'):
        """
        Gets GNSS proto parameter value from SMOD.
        :param parameter: GNSS proto parameter to get, e.g. 'versionMajor', 'versionMinor'
        :type parameter: str
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        :return: GNSS proto parameter value
        :rtype: str
        :raises GnssInfoError: if GNSS proto parameter cannot be found in GNSS proto info
        """
        if self.proto_info is None:
            self._get_proto_info(bts_type=bts_type)

        try:
            return re.search(f'{parameter}: (.*)', self.proto_info, re.IGNORECASE).group(1).strip('"\n\r')
        except AttributeError:
            raise GnssInfoError(
                f'Cannot get GNSS {parameter} from SMOD.\n'
                f'Please check if GNSS is in configuration or if required parameter exists in info.\n'
                f'GNSS proto info: {self.proto_info}')

    @log_input_and_output
    def _get_smod_path_to_gnss_sw(self, bts_type='GNB'):
        """
        Gets path to GNSS software from current BTS software package in SMOD.
        GNSS software is searched in '/rom/swpool/GPS/' directory by GNSS HW type and version.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        :return: path to GNSS SW in SMOD, e.g.: '/rom/swpool/GPS/FYGM3042-MC-RT_V002081.bin'
        :rtype: str
        :raises GnssInfoError: if GNSS SW file cannot be found
        """
        gnss_hw_type = self._get_gnss_parameter_value('hwType', bts_type=bts_type)
        gnss_hw_version = self._get_gnss_parameter_value('hwVersion', bts_type=bts_type)

        sw_path = self._execute_on_smod(command=f'find /rom/swpool/GPS -name "*{gnss_hw_type}*" -and '
                                                f'-name "*{gnss_hw_version}*" '
                                                f'-and -name "*bin"', bts_type=bts_type).rstrip('\r\n')

        if not sw_path:
            raise GnssInfoError(f'Cannot find GNSS SW file in SMOD for HW type: {gnss_hw_type}, '
                                f'HW version: {gnss_hw_version}.')
        return sw_path

    @log_input_and_output
    def _get_gnss_sw_version_in_bts_packages(self, bts_type='GNB'):
        """
        Gets GNSS SW package version from BTS packages.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        :return: tuple with major sw version and minor sw version of GNSS, e.g.:
                 ('2', '71')
        :rtype: tuple
        """
        gnss_sw_path = self._get_smod_path_to_gnss_sw(bts_type=bts_type)

        version = gnss_sw_path.split('_V')[-1].rstrip('.bin').lstrip('0')
        major = ''
        for num_index, number in enumerate(version):
            if number != '0':
                major += number
            else:
                if version[num_index + 1] == '0':
                    major += number
                else:
                    break

        minor = version.lstrip(major).lstrip('0')
        return major, minor

    @log_input_and_output
    def _is_current_gnss_sw_version_identical_to_bts_package(self, bts_type='GNB'):
        """
        Checks if current GNSS SW version is identical to GNSS SW version in BTS packages.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        :return: True if GNSS SW version in SMOD is identical to GNSS SW version in BTS packages, False otherwise
        :rtype: bool
        """
        gnss_major_sw_version_smod = self._get_gnss_parameter_value('swVersionMajor', bts_type=bts_type)
        gnss_minor_sw_version_smod = self._get_gnss_parameter_value('swVersionMinor', bts_type=bts_type)

        gnss_sw_version_bts_packages = self._get_gnss_sw_version_in_bts_packages(bts_type=bts_type)

        return (gnss_major_sw_version_smod, gnss_minor_sw_version_smod) == gnss_sw_version_bts_packages

    @log_input_and_output
    def _enable_gnss_device(self, bts_type='GNB'):
        """
        Enables GNSS device in SMOD.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        """
        major_proto_version = self._get_gnss_proto_parameter_value('versionMajor', bts_type=bts_type)
        minor_proto_version = self._get_gnss_proto_parameter_value('versionMinor', bts_type=bts_type)

        self._execute_on_smod(
            command=f'{self.proto_cmd} -t update --args  versionMajor={major_proto_version}:'
                    f'versionMinor={minor_proto_version}:enable=True',
            bts_type=bts_type)
        self._execute_on_smod(
            command=f'{self.device_cmd} --proto GNSS/device -t execute --action setEnable --args enable=1',
            bts_type=bts_type)

    @log_input_and_output
    def _execute_on_smod(self, command, bts_type="GNB"):
        """
        Executes command on SMOD.
        :param command: command to execute on SMOD
        :type command: str
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        """
        credentials = get_ssh_connection_credentials(bts_type=bts_type)
        try:
            self.smod.connect_to(credentials['host'], credentials['username'], credentials['password'])
            return self.smod.execute(command)
        finally:
            self.smod.close_connection()

    @log_input_and_output
    def _get_device_info(self, bts_type='GNB'):
        """
        Gets GNSS device information from SMOD.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        """
        self.device_info = self._execute_on_smod(command=self.device_cmd + ' -t query', bts_type=bts_type)

    @log_input_and_output
    def _get_proto_info(self, bts_type='GNB'):
        """
        Gets GNSS proto information from SMOD.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        """
        self.proto_info = self._execute_on_smod(command=self.proto_cmd + ' -t query', bts_type=bts_type)

    @log_input_and_output
    def _wait_for_sw_upgrade_status_finished(self, wait_time=20, bts_type='GNB'):
        """
        Waits for GNSS software update to finish for specified time.
        :param wait_time: maximum waiting time to complete GNSS software update in minutes
        :param wait_time: int
        :param bts_type: type of bts, can be 'GNB' or 'ENB'; default value: 'GNB'
        :type bts_type: str
        :raises GnssSwUpdateError: if GNSS software update not successful within given minutes
        """
        for time_check in range(wait_time):
            sleep(60)
            update_status = self._execute_on_smod(
                command=f'{self.device_cmd}/STATUS-1 --proto GNSS/status -t query|grep -i swUpgradeStatus',
                bts_type=bts_type)
            if 'ESwUpgradeStatus_Finished' in update_status:
                break
        else:
            raise GnssSwUpdateError('GNSS software update not successful within 20 minutes.')
